INSERT INTO "revisions" VALUES('990f70efc2513e8eba55f280dc24df048221eae8e82106153db4899543339ed2','legacy_resources','{"entry":"main.nex","files":{"main.nex":"module legacy_resources;\npub struct Packet<T:wire>{data:T;scale:f64;}\nfn identity<T:wire>(value:T)->T{return unwrap(decode_json<T>(encode_json(value)));}\nfn capture(value:bytes)->(fn()->bytes){return fn()->bytes{return value;};}\nserver fn preserved_file(path:str)->result<bytes>!{fs}{return file_read_bytes(path);}\nserver fn reader()->(server fn(str)->result<bytes>!{fs}){return preserved_file;}\nfn main()->unit!{io}{\n let original:bytes=unwrap(bytes([0,255,128,65]));\n print(identity(Packet<bytes>(capture(original)(),1.25)));\n print(unwrap(decode_utf8(utf8_bytes(\"Я\\u0000🧠\"))));\n}\ntest fn preserved()->unit{\n let original:bytes=unwrap(bytes([0,255,128,65]));\n assert(capture(original)()==original);\n assert(identity(Packet<bytes>(original,1.25)).data==original);\n assert(encode_base64(slice(original,1,2))==\"/4A=\");\n}\n"},"schema":"nex.sources/1"}','/Users/sae/projects/NEX/build/genuine-language-013-capture/0.13/main.nex','2026-10-18T05:31:40.364Z','0.13');
